import React, { useState, useEffect, useRef } from "react"
import {
  Streamlit,
  StreamlitComponentBase,
  withStreamlitConnection,
} from "streamlit-component-lib"
import "./FillInTheBlanks.css" // We'll create this for styling

interface FillInTheBlanksProps {
  args: {
    question_text_full: string
    answer_to_blank: string
    default_value?: string // Value from Streamlit (Python)
    disabled?: boolean
  }
}

const FillInTheBlanks: React.FC<FillInTheBlanksProps> = (props) => {
  const { question_text_full, answer_to_blank, default_value, disabled } = props.args
  const [inputValue, setInputValue] = useState<string>(default_value || "")
  const inputRef = useRef<HTMLInputElement>(null)

  // When the default_value from Python changes, update our state
  useEffect(() => {
    if (default_value !== undefined && default_value !== inputValue) {
        setInputValue(default_value)
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [default_value]) // Only re-run if default_value changes

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const newValue = event.target.value
    // Only allow input that matches the length of the original answer
    if (newValue.length <= answer_to_blank.length) {
      setInputValue(newValue)
      Streamlit.setComponentValue(newValue) // Send value back to Streamlit
    }
  }

  // Split the question text
  const parts = question_text_full.split(answer_to_blank)
  const beforeText = parts[0]
  const afterText = parts.length > 1 ? parts.slice(1).join(answer_to_blank) : ""

  // Calculate width for the input based on answer length
  // This is an approximation, might need fine-tuning with CSS
  const inputWidth = `${answer_to_blank.length * 0.9}em` // Approx 0.9em per char

  useEffect(() => {
    Streamlit.setFrameHeight()
  })

  return (
    <div className={`fill-in-the-blanks-container ${disabled ? 'disabled' : ''}`}>
      <span>{beforeText}</span>
      <input
        ref={inputRef}
        type="text"
        value={inputValue}
        onChange={handleInputChange}
        onBlur={() => Streamlit.setComponentValue(inputValue)} // Ensure value is sent on blur
        style={{ width: inputWidth, minWidth: '30px' }} // Ensure a minimum width
        maxLength={answer_to_blank.length}
        disabled={disabled}
        className="blank-input"
      />
      <span>{afterText}</span>
    </div>
  )
}

export default withStreamlitConnection(FillInTheBlanks)
